/* 源文件 --status-read-color 对应用户侧时间后的「已读」字样。
 * 此处为白框的本地会话样式文案，不改变/伪造服务端送达或阅读事件。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-user .sully-chat-message-timestamp{
  color:#9a9a9a!important;font-size:10px!important;opacity:1!important;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-user .sully-chat-message-timestamp::after{
  content:"已读"!important;color:#c3c3c3!important;
  display:inline!important;margin-left:5px!important;white-space:nowrap!important;
  font:400 10px/1.3 system-ui,sans-serif!important;
}
@media(max-width:390px){
 .sully-chat-root:not(.sully-chat-group-root) .sully-chat-header button[aria-label="电话"]{right:53px!important}
 .sully-chat-root:not(.sully-chat-group-root) .sully-chat-header .sully-chat-trigger{right:7px!important}
}

/* Source-only status footer spacing: leave space after the last user time + 已读 label. */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-user.sully-chat-message-group-last:not(.sully-chat-message-module){
  margin-bottom:24px!important;
}


/* 请求添加好友 · 仅缩小气泡 v13
 * 之前已经调好的顶部申请框、底部输入框完全保留。
 * 只缩小文字气泡；不改头像尺寸、媒体消息、转账或按钮功能。
 */
.sully-chat-root .sully-bubble-user,
.sully-chat-root .sully-bubble-ai{
  font-size:12px!important;
  line-height:1.38!important;
  padding:5px 9px!important;
  border-radius:13px!important;
  max-width:min(57vw,100%)!important;
}


/* 请求添加好友 · 渐变爱心与首条气泡解耦 v14
 * 问题：原本把五心 ::before 挂在消息内容 flex 项上，同时组首气泡再加 8px 上边距。
 * 修复：恢复原文件把五心绝对定位在气泡自身的 ::after，完全脱离排版；
 * 消除多余 8px 气泡位移，保留外层既有的分组间距、气泡大小和全部原 SVG。
 * 仅作用于当前主题已有 CSS，不改头部、底栏、头像、其它样式与操作。
 */
/* 旧布局挂点不再绘制，避免两套渐变爱心叠加。 */
.sully-chat-root .sully-chat-message.sully-chat-message-group-first:has(.sully-bubble-user) .sully-chat-message-content::before,
.sully-chat-root .sully-chat-message.sully-chat-message-group-first:has(.sully-bubble-ai) .sully-chat-message-content::before {
 content:none!important;
 display:none!important;
}
/* 复用当前预设前半部已保留的原文件 5 个 SVG background-image，
 * 只解开 v10 对气泡 ::after 的隐藏；无须复制或重制图片。 */
.sully-chat-root .sully-bubble-user.sully-bubble-group-first::after,
.sully-chat-root .sully-bubble-ai.sully-bubble-group-first::after {
 content:""!important;
 display:block!important;
 position:absolute!important;
 top:-13px!important;
 width:63px!important;
 height:11px!important;
 pointer-events:none!important;
}
/* 爱心上方使用现有 28px 组间距，不再给组首气泡加第二层 8px 位移。 */
.sully-chat-root .sully-bubble-user.sully-bubble-group-first,
.sully-chat-root .sully-bubble-ai.sully-bubble-group-first {
 margin-top:0!important;
}


/* 请求添加好友 · 气泡内层文字与独立引用遮挡修复 v15
 * 对照原文件 202-224 行独立引用、768-775 行文字气泡。
 * 与本主题现有 v13 气泡压缩尺寸保持一致，禁止修改顶栏/底栏/头像。
 * 糯米机气泡里的 .sully-facebook-bubble-text 自带 text-[15px]，
 * 之前仅缩小外壳不会缩小实际文字，这是先前尺寸没变的原因。
 */
.sully-chat-root:not(.sully-chat-group-root) .sully-bubble-user > .sully-facebook-bubble-text,
.sully-chat-root:not(.sully-chat-group-root) .sully-bubble-ai > .sully-facebook-bubble-text{
 font-size:12px!important;
 line-height:1.38!important;
}
/* 源文件的引用要作为气泡下方的独立 >> 文字行，而不是藏进气泡里。
 * 宽度不跟随“嗯”等短气泡被限制为原气泡的 90%。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-bubble-user > .sully-chat-reply,
.sully-chat-root:not(.sully-chat-group-root) .sully-bubble-ai > .sully-chat-reply{
 position:absolute!important;
 top:calc(100% + 5px)!important;
 width:max-content!important;
 min-width:0!important;
 max-width:min(72vw,280px)!important;
 overflow:visible!important;
 white-space:nowrap!important;
 z-index:15!important;
 line-height:1.3!important;
 opacity:1!important;
}
/* 引用和时间戳同处气泡下方，显式错层，防止“已读”压住 >> 引用。
 * 仅在含引用的文字消息增加实际滚动空间，其他消息不变。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message:not(.sully-chat-message-module):has(.sully-chat-reply){
 margin-bottom:48px!important;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message:not(.sully-chat-message-module):has(.sully-chat-reply) .sully-chat-message-timestamp{
 top:calc(100% + 25px)!important;
}
/* 原文件引用图片 28×28px，图片引用额外留出其自身高度。 */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message:not(.sully-chat-message-module):has(.sully-chat-reply img){
 margin-bottom:63px!important;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message:not(.sully-chat-message-module):has(.sully-chat-reply img) .sully-chat-message-timestamp{
 top:calc(100% + 40px)!important;
}


/* 请求添加好友 · 用户气泡右边线稳定对齐 v16
 * 原生消息每条是独立 flex 行，长短文字和五心/引用可能改变内容包裹宽度。
 * 仅锁定用户普通消息的右边界，不改变任何气泡的尺寸、头像、顶/底栏和其他主题。
 */
.sully-chat-root:not(.sully-chat-group-root)
 .sully-chat-message-user:not(.sully-chat-message-module) > .sully-chat-message-content {
  margin-left:auto!important;
  margin-right:3rem!important; /* 保持原生 mr-12，为用户头像留位 */
  flex:0 1 auto!important;
  min-width:0!important;
  max-width:72%!important; /* 保留原生 max-w-[72%] */
}
.sully-chat-root:not(.sully-chat-group-root)
 .sully-chat-message-user:not(.sully-chat-message-module) > .sully-chat-message-content > div:not([aria-hidden="true"]) {
  align-items:flex-end!important;
}
.sully-chat-root:not(.sully-chat-group-root)
 .sully-chat-message-user:not(.sully-chat-message-module) .sully-bubble-user {
  align-self:flex-end!important;
  margin-left:auto!important;
  margin-right:0!important;
}
/* 五心随气泡的右侧定位，绝不参与真实 flex 排列。 */
.sully-chat-root:not(.sully-chat-group-root)
 .sully-chat-message-user.sully-chat-message-group-first .sully-bubble-user::after {
  right:6px!important;
  left:auto!important;
  position:absolute!important;
  pointer-events:none!important;
}
